          "mechanic2": "巣は類義語を要求してるの！意味のある大きな単語を！",
          "lowTime1": "チクタク！私のハチミツだってそんなに時間かからないわ！",
          "victory": "私に...勝った？女王に？また来るわよ。（わかった？ビー？ハチだから。）",
